INSERT INTO public.producers (id, slug, nome_artistico, instagram, spotify, cidade, bio, foto_perfil_url, foto_perfil_path, status, created_at, updated_at, nome_civil, cpf, nome_artistico_creditos, email_comercial, email_royalties, texto_creditos, texto_registro, texto_royalties) VALUES ('b2bdb869-5258-4b40-bbee-adf02e29f04c', 'gau-beats', 'Gau Beats', '@gaubeats', NULL, 'Porto Alegre', 'Produtora musical, DJ, Beatmaker e Produtora Cultural, atuante na área musical dês Junho de 2020 junto a gravadora Gueto Anonimato Records em Porto Alegre - RS. Possuí um amplo catálogo de lançamentos autorais e também  assinando produções de artistas de todo território nacional, em ritmos que fazem parte da cultura Hip Hop e também em ritmos oriundos da música eletrônica. Participou de grandes eventos como DJ e também de coletâneas de música eletrônica (nacional e internacional) com faixas exclusivas produzidas em estúdio. Iniciou sua jornada como arte educadora em 2025 ministrando o curso de Produção Musical (focado na prática da criação de Beats) através da iniciativa da Associação Alvo Cultural.', NULL, 'producers/new/avatar-1783107896388.jpg', 'ativa', '2026-07-03 19:45:00.788546+00', '2026-07-03 19:45:00.788546+00', 'Adrienni Rodrigues da Rosa', '85728667015', 'Gau Beats', 'contatogaubeats@gmail.com', 'bygaubeats@gmail.com', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.producers (id, slug, nome_artistico, instagram, spotify, cidade, bio, foto_perfil_url, foto_perfil_path, status, created_at, updated_at, nome_civil, cpf, nome_artistico_creditos, email_comercial, email_royalties, texto_creditos, texto_registro, texto_royalties) VALUES ('da23b935-d51b-4376-917c-1d29d7549edf', 'anonima-beats', 'Anonima Beats', '@anonimabeats', NULL, 'Mato Grosso', 'Beatmaker e produtora musical, atua desde 2020 no desenvolvimento de artistas independentes. Cria beats autorais, produz e direciona artisticamente, transformando referências em projetos com identidade própria.', NULL, 'producers/new/avatar-1781112277612.jpeg', 'ativa', '2026-06-10 17:50:13.123845+00', '2026-07-06 16:19:36.47286+00', 'Roberta Beatriz da Silva Wenceslau', '04425516141', 'Anônima beats', 'anonimabeats@hotmail.com', 'anonimabeats@hotmail.com', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.producers (id, slug, nome_artistico, instagram, spotify, cidade, bio, foto_perfil_url, foto_perfil_path, status, created_at, updated_at, nome_civil, cpf, nome_artistico_creditos, email_comercial, email_royalties, texto_creditos, texto_registro, texto_royalties) VALUES ('77df563f-3ccc-4c56-bc31-8e3e6507047c', 'ayla', 'Ayla On The Beat', '@aylaonthebeat', NULL, NULL, 'Ayla On The Beat é uma produtora musical, compositora e diretora criativa brasileira reconhecida por sua atuação no mercado internacional. Membra votante do Grammy Latino e indicada a Produtora Musical do Ano pelo WME Billboard Brasil, já produziu para artistas do Brasil, Estados Unidos e Coreia do Sul, com destaque para trabalhos com Taboo (Black Eyed Peas) e Yves (LOONA).', NULL, 'producers/new/avatar-1786054165686.png', 'ativa', '2026-08-06 22:11:49.03755+00', '2026-08-06 22:11:49.03755+00', 'Fernanda Raíza Barbosa', '08596833978', 'Ayla On The Beat', 'aylaonthebeat@gmail.com', 'itsaylabeats@gmail.com', NULL, NULL, NULL) ON CONFLICT DO NOTHING;
