INSERT INTO public.feedback (id, rating, type, area, message, wants_reply, contact_name, contact_email, contact_whatsapp, purchase_request_id, release_id, origin, status, internal_notes, user_agent, created_at, updated_at) VALUES ('9b47321d-4594-4827-8308-c33e370e37b8', '5', 'sugestao', NULL, 'Muito acessivel de usar, adorei. Mas acabei enviando antes da ultima revisão, não sei se teclei errado ou o tempo expirou, mas consta como enviado. É pra ter tudo, mas pode ter passado algo despercebido. A sugestão é ser possível a gente reabrir o lançamento enviado e edita-lo na plataforma, em caso de envio acidental. No mais, ótima experiencias.', 'false', NULL, NULL, NULL, NULL, NULL, 'pos_lancamento', 'resolvido', NULL, NULL, '2026-07-22 14:30:33.100805+00', '2026-07-24 07:07:01.863162+00') ON CONFLICT DO NOTHING;
